    print(cAPS_lOCK(string))

def cAPS_lOCK(string):
    if len(string) >= 1 :
        return string.lower() if string.isupper() else string.capitalize() if len(string) == 1 or string[1:] == string[1:].upper() else string
    if string[0] == string[1]:
        return string.lower()
    elif string[1:].isupper():
        return string.capitalize()
    elif string.isupper():
        return string.capitalize()
    else :
        return string

