def caps(stri):
    stri=str(stri)
    count=0
    t=0
    for d in stri:
        if d in "A B C D E F G H I K L M N O P Q R S T V X Y Z ":
            count+=1
    if count==len(stri):
        return stri.lower()
    if stri[0] not in 'A B C D E F G H I K L M N O P Q R S T V X Y Z ' or count != len(stri) - 1:
        return stri.lower() if stri.isupper() else stri.capitalize() if len(stri) == 1 or stri[1:] == stri[1:].upper() else stri
    return stri
